skins.css:
/* RAGNAROK - the real client is pale, cool and blue-white. Every surface is a
   plate with thickness: lit along the top and left, shaded along the bottom
   and right. Nothing floats, nothing fades, and a button goes IN when pressed.
   No layout is touched. Only the drawing of each box changes. */

body { letter-spacing: var(--track-body) }

/* A title bar is pale blue with dark text, not a saturated stripe. */
header {
  background: linear-gradient(180deg, var(--surface-3), var(--surface-2));
  color: var(--text-1);
  border-bottom: var(--border-width) solid var(--border-strong);
  box-shadow: inset 1px 1px 0 rgba(255,255,255,.9);
}
header .logo {
  font-family: var(--font-display);
  font-size: var(--f-2);
  color: var(--accent);
  letter-spacing: var(--track-cap);
}
header .logo b { color: var(--text-1) }

/* ---- plates ---- */
.card, .mb-sheet, .mb-toast, .mb-menu {
  background: var(--surface-1);
  border: var(--border-width) solid var(--border);
  box-shadow: var(--e-2);
}

.mb-sheet-head {
  background: linear-gradient(180deg, var(--surface-3), var(--surface-2));
  color: var(--text-1);
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  border-bottom: var(--border-width) solid var(--border);
  box-shadow: inset 1px 1px 0 rgba(255,255,255,.9);
}
.mb-sheet-head .mb-grab { background: var(--border-strong) }

h2 {
  font-family: var(--font-display);
  color: var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

/* ---- wells: rows, inputs, tracks. Pressed into the plate. ---- */
.item, .mb-input, .mb-sel, .mb-range, .mb-sw {
  background: var(--surface-2);
  border: var(--border-width) solid var(--border);
  box-shadow: var(--bevel-in);
}

/* ---- buttons: raised, and they go in under the finger ---- */
button.mb-btn, .mb-act, button.chk, #fab, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: var(--surface-3);
  color: var(--text-1);
  border: var(--border-width) solid var(--border);
  box-shadow: var(--e-1);
  transition: none;
}
button.mb-btn:active, .mb-act:active, button.chk:active,
#fab:active, .mb-chip:active, .mb-x:active, .mb-opt:active {
  box-shadow: var(--bevel-in);
  transform: translate(1px, 1px);
}

#fab {
  background: var(--accent);
  color: var(--accent-fg);
  border-radius: 0;
  font-family: var(--font-display);
  font-size: var(--f-5);
}

button.chk { border-radius: 0 }
button.chk.on { background: var(--accent); color: var(--accent-fg); box-shadow: var(--e-1) }

.stat { background: var(--surface-2); box-shadow: var(--bevel-in) }
.stat b { font-family: var(--font-display); color: var(--accent) }

.mb-opt:hover, .mb-chip.on { background: var(--accent); color: var(--accent-fg) }

/* SYSTEM - a levelling-up status window. Light comes OFF the surfaces instead
   of falling onto them, every frame is a hairline, and the corners are cut
   with brackets rather than rounded. */

body { letter-spacing: var(--track-body) }

header {
  background: transparent;
  border-bottom: var(--border-width) solid var(--border);
  box-shadow: 0 1px 0 rgba(127,227,255,.10);
}
header .logo {
  font-family: var(--font-display);
  color: var(--text-1);
  text-shadow: 0 0 14px var(--accent);
}
header .logo b { color: var(--accent); text-shadow: 0 0 18px var(--accent) }

/* A panel is a pane of lit glass, not a solid card. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  background: linear-gradient(180deg, rgba(127,227,255,.05), rgba(127,227,255,.012));
  border: var(--border-width) solid var(--border);
  box-shadow: var(--e-1);
}
/* Bracket corners. Two pseudo-elements on opposite corners, no new markup. */
.card::before, .card::after {
  content: ''; position: absolute; width: 15px; height: 15px;
  border: 2px solid var(--accent); pointer-events: none;
}
.card::before { top: -1px; left: -1px; border-right: 0; border-bottom: 0 }
.card::after { bottom: -1px; right: -1px; border-left: 0; border-top: 0 }

h2 {
  font-family: var(--font-display);
  color: var(--accent);
  text-shadow: 0 0 12px var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

/* A row is a ruled line in a readout, not a filled pill. */
.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 2px; border-color: var(--border-strong) }
.chk.on { box-shadow: var(--e-2); border-color: var(--accent) }

/* The numbers are the whole point of a status window, so they glow. */
.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { color: var(--text-1); text-shadow: 0 0 16px var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--border-strong);
}
button.mb-btn:active, .mb-act:active { background: var(--accent); color: var(--accent-fg) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); box-shadow: var(--e-2) }

.mb-input, .mb-sel { background: rgba(127,227,255,.05); border-color: var(--border) }
#fab { box-shadow: var(--e-3); border: var(--border-width) solid var(--accent) }

/* MONARCH - black and gold. Nothing floats and almost nothing is filled: the
   whole design is hairlines, capitals and empty space. */

body { letter-spacing: var(--track-body) }

header { background: var(--bg); border-bottom: var(--border-width) solid var(--accent) }
header .logo { font-family: var(--font-display); color: var(--accent) }
header .logo b { color: var(--text-2) }

/* A card is a ruled box with a second line just inside it. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--bg);
  border: var(--border-width) solid var(--accent);
  box-shadow: inset 0 0 0 3px var(--bg), inset 0 0 0 4px var(--border);
  padding: var(--s-5);
}

h2 {
  font-family: var(--font-display);
  color: var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 0; border-color: var(--accent) }
.chk.on { background: var(--accent); color: var(--accent-fg) }

.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--accent);
  border-radius: 0;
}
button.mb-btn:active, .mb-act:active, .mb-chip:active,
.mb-btn.go { background: var(--accent); color: var(--accent-fg) }

.mb-input, .mb-sel { background: transparent; border-color: var(--border);
  border-radius: 0; color: var(--text-1) }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg);
  font-family: var(--font-display) }

/* ORNATE - a grey plate in a gold frame, with a diamond on every rule. The
   flourishes are pseudo-elements on things that already exist, so no app grows
   a single new element. */

body { letter-spacing: var(--track-body) }

header { background: var(--surface-1); border-bottom: var(--border-width) solid var(--accent) }
header .logo { font-family: var(--font-display); color: var(--accent) }
header .logo b { color: var(--text-1) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  background: var(--surface-1);
  border: var(--border-width) solid var(--accent);
  box-shadow: inset 0 0 0 4px var(--surface-1), inset 0 0 0 5px var(--border);
  padding: var(--s-5);
}
/* Gold corner flourishes on opposite corners, drawn rather than fetched. */
.card::before, .card::after {
  content: ''; position: absolute; width: 16px; height: 16px;
  border: 2px solid var(--accent); pointer-events: none;
}
.card::before { top: 5px; left: 5px; border-right: 0; border-bottom: 0 }
.card::after { bottom: 5px; right: 5px; border-left: 0; border-top: 0 }

/* A heading is centred and ruled, and the rule is broken by a diamond. */
h2 {
  position: relative;
  font-family: var(--font-display);
  text-align: center;
  color: var(--accent);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-3);
}
h2::after {
  content: '\25C6';
  position: absolute; left: 50%; bottom: -7px; transform: translateX(-50%);
  background: var(--surface-1); padding: 0 6px;
  color: var(--accent); font-size: 10px; line-height: 1;
}

.item { background: transparent; border-bottom: var(--border-width) solid var(--border) }
.item.on .nm { color: var(--text-muted) }

.chk { border-radius: 0; border-color: var(--accent) }
.chk.on { background: var(--accent); color: var(--accent-fg) }

.stat { background: transparent; border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--accent);
  border: var(--border-width) solid var(--accent);
  border-radius: 0;
}
button.mb-btn:active, .mb-act:active, .mb-btn.go {
  background: var(--accent); color: var(--accent-fg);
}
.mb-input, .mb-sel { background: var(--surface-2); border-color: var(--border); border-radius: 0 }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg);
  border: 2px solid var(--border-strong); font-family: var(--font-display) }

/* DECK - a presentation slide. A deep blue gradient, hairline rules, generous
   capitals, and rows that band the way a table on a slide does. */

body { letter-spacing: var(--track-body) }

header { background: transparent; border-bottom: var(--border-width) solid var(--border) }
header .logo { font-family: var(--font-display); color: var(--text-1) }
header .logo b { color: var(--accent) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: rgba(255,255,255,.055);
  border: var(--border-width) solid var(--border);
}

h2 {
  font-family: var(--font-display);
  color: var(--text-1);
  border-bottom: var(--border-width) solid var(--border);
  padding-bottom: var(--s-2);
}

/* Banded rows. It has to work whether or not the row is wrapped for the swipe
   gesture, so both shapes are named. */
.item, .list > *:nth-child(odd) .item { background: rgba(255,255,255,.05) }
.list > *:nth-child(even) .item, .item:nth-child(even) { background: rgba(255,255,255,.10) }
.item.on .nm { color: var(--text-muted) }

.chk { border-color: var(--border-strong) }
.chk.on { background: var(--accent); color: var(--accent-fg); border-color: var(--accent) }

.stat { background: rgba(255,255,255,.07); border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--text-1) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display);
  letter-spacing: var(--track-cap);
  background: transparent;
  color: var(--text-1);
  border: var(--border-width) solid var(--border-strong);
}
button.mb-btn:active, .mb-act:active { background: rgba(255,255,255,.16) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); border-color: var(--accent) }

.mb-input, .mb-sel { background: rgba(255,255,255,.09); border-color: var(--border);
  color: var(--text-1) }
#fab { background: var(--accent); color: var(--accent-fg) }

/* BLOCKS - everything is a solid rectangle of colour. No rounding, no shadow,
   no gradient: separation comes from the blocks butting up against each other,
   the way a tiled interface does. */
body { letter-spacing: var(--track-body) }

header { background: var(--accent); color: var(--accent-fg) }
header .logo { font-family: var(--font-display); color: var(--accent-fg) }
header .logo b { color: var(--accent-fg); opacity: .6 }
header .mb-btn { background: rgba(0,0,0,.22); color: var(--accent-fg); border: 0 }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1); border: 0; border-left: 6px solid var(--accent);
}
h2 { font-family: var(--font-display); color: var(--text-1) }

/* Rows are stacked blocks with a hairline of page showing between them. */
.item { background: var(--surface-2); border: 0; margin-bottom: 2px }
.item.on { background: var(--surface-3) }
.chk { border-radius: 0; border-width: 3px }
.chk.on { background: var(--accent); border-color: var(--accent); color: var(--accent-fg) }

.stat { background: var(--surface-2); border: 0 }
.stat b { font-family: var(--font-display) }
.bars i { border-radius: 0 }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: var(--surface-3); color: var(--text-1); border: 0; border-radius: 0;
}
.mb-btn.go { background: var(--accent); color: var(--accent-fg) }
.mb-input, .mb-sel { background: var(--surface-2); border: 0; border-radius: 0;
  border-bottom: 3px solid var(--accent) }
#fab { border-radius: 0; background: var(--accent); color: var(--accent-fg) }

/* LEGO - bricks. Slightly rounded, glossy on top, dark underneath, and every
   panel wears a row of studs. The studs are a repeating gradient on a
   pseudo-element, so nothing is fetched and no app grows an element. */
body { letter-spacing: var(--track-body) }

header {
  background: linear-gradient(180deg, rgba(255,255,255,.4), rgba(0,0,0,.12)), var(--accent);
  color: var(--accent-fg);
  box-shadow: inset 0 -4px 0 rgba(0,0,0,.22);
}
header .logo { font-family: var(--font-display); color: var(--accent-fg);
  text-shadow: 0 2px 0 rgba(0,0,0,.28) }
header .logo b { color: #FFD500 }

.card, .mb-sheet, .mb-menu, .mb-toast {
  position: relative;
  background: linear-gradient(180deg, rgba(255,255,255,.55), rgba(0,0,0,.06)), var(--surface-1);
  border: 0;
  box-shadow: inset 0 -5px 0 rgba(0,0,0,.16), 0 3px 0 rgba(0,0,0,.18);
  padding-top: var(--s-5);
}
/* the studs */
.card::before {
  content: ''; position: absolute; top: 6px; left: var(--s-4); right: var(--s-4); height: 11px;
  background-image: radial-gradient(circle at 7px 5px,
    rgba(255,255,255,.75) 0 3.5px, rgba(0,0,0,.14) 4px 5px, transparent 5.5px);
  background-size: 22px 11px; background-repeat: repeat-x; pointer-events: none;
}
h2 { font-family: var(--font-display); color: var(--text-1) }

.item {
  background: linear-gradient(180deg, rgba(255,255,255,.5), rgba(0,0,0,.05)), var(--surface-2);
  box-shadow: inset 0 -3px 0 rgba(0,0,0,.14);
}
.chk { border-width: 3px; border-color: var(--border-strong) }
.chk.on { background: var(--accent); border-color: var(--accent); color: var(--accent-fg) }

.stat { background: linear-gradient(180deg, rgba(255,255,255,.5), rgba(0,0,0,.05)), var(--surface-2);
  box-shadow: inset 0 -3px 0 rgba(0,0,0,.14) }
.stat b { font-family: var(--font-display) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: linear-gradient(180deg, rgba(255,255,255,.5), rgba(0,0,0,.06)), var(--surface-3);
  color: var(--text-1); border: 0;
  box-shadow: inset 0 -4px 0 rgba(0,0,0,.18);
}
button.mb-btn:active, .mb-act:active { box-shadow: inset 0 3px 0 rgba(0,0,0,.18);
  transform: translateY(2px) }
.mb-btn.go { background: linear-gradient(180deg, rgba(255,255,255,.4), rgba(0,0,0,.1)), var(--accent);
  color: var(--accent-fg) }
.mb-input, .mb-sel { background: var(--surface-2); box-shadow: inset 0 3px 0 rgba(0,0,0,.12) }
#fab { background: linear-gradient(180deg, rgba(255,255,255,.45), rgba(0,0,0,.12)), var(--accent);
  color: var(--accent-fg); box-shadow: inset 0 -5px 0 rgba(0,0,0,.2), 0 3px 0 rgba(0,0,0,.2) }

/* MINECRAFT - the inventory screen. Light grey stone plates with a hard dark
   outline, lit on the top-left and shaded on the bottom-right, and absolutely
   nothing rounded or smoothed anywhere. */
body { image-rendering: pixelated; letter-spacing: var(--track-body) }

header {
  background: var(--surface-2);
  border-bottom: 3px solid var(--border-strong);
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.55);
}
header .logo { font-family: var(--font-display); font-size: var(--f-2);
  color: var(--text-1); text-shadow: 2px 2px 0 rgba(0,0,0,.28) }
header .logo b { color: var(--accent) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1);
  border: 3px solid var(--border-strong);
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.6), inset -2px -2px 0 rgba(0,0,0,.28);
}
h2 { font-family: var(--font-display); font-size: 11px; color: var(--text-1);
  text-shadow: 1px 1px 0 rgba(255,255,255,.5) }

/* An inventory slot: pressed in, always. */
.item, .mb-input, .mb-sel {
  background: var(--surface-2);
  border: 2px solid var(--border);
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.3), inset -2px -2px 0 rgba(255,255,255,.55);
}
.chk { border-radius: 0; border-width: 3px; border-color: var(--border-strong) }
.chk.on { background: var(--accent); border-color: var(--border-strong); color: var(--accent-fg) }

.stat { background: var(--surface-2);
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.3), inset -2px -2px 0 rgba(255,255,255,.55) }
.stat b { font-family: var(--font-display); font-size: var(--f-3); color: var(--accent) }
.bars i { border-radius: 0 }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt, #fab {
  font-family: var(--font-display); font-size: 10px; letter-spacing: 0;
  background: var(--surface-3); color: var(--text-1);
  border: 2px solid var(--border-strong); border-radius: 0;
  box-shadow: inset 2px 2px 0 rgba(255,255,255,.6), inset -2px -2px 0 rgba(0,0,0,.28);
  transition: none;
}
button.mb-btn:active, .mb-act:active, #fab:active {
  box-shadow: inset 2px 2px 0 rgba(0,0,0,.3), inset -2px -2px 0 rgba(255,255,255,.5);
}
#fab { background: var(--accent); color: var(--accent-fg); font-size: var(--f-4) }

/* DRAGON QUEST - the command window. Solid navy, a thick white frame with a
   second line inside it, white text, square corners, and nothing else at all.
   The restraint is the look. */
body { letter-spacing: var(--track-body) }

header {
  background: var(--surface-1);
  border-bottom: 4px solid var(--text-1);
  box-shadow: inset 0 0 0 2px var(--surface-1), inset 0 -8px 0 -6px var(--text-1);
}
header .logo { font-family: var(--font-display); color: var(--text-1) }
header .logo b { color: var(--accent) }

/* The signature: white frame, gap, white frame. */
.card, .mb-sheet, .mb-menu, .mb-toast {
  background: var(--surface-1);
  border: 4px solid var(--text-1);
  box-shadow: inset 0 0 0 2px var(--surface-1), inset 0 0 0 4px var(--text-1);
  padding: var(--s-5);
}
h2 { font-family: var(--font-display); color: var(--accent);
  border-bottom: 2px solid var(--border); padding-bottom: var(--s-2) }

.item { background: transparent; border: 0 }
/* Selection is the pointing arrow, the way a command list works. */
.item.on .nm { color: var(--text-2) }
.item::before { content: ''; width: 0; height: 0; flex: 0 0 auto; margin-right: -6px;
  border-left: 7px solid transparent; border-top: 5px solid transparent;
  border-bottom: 5px solid transparent }
.item.on::before { border-left-color: var(--accent) }

.chk { border-radius: 0; border-width: 2px; border-color: var(--text-1) }
.chk.on { background: var(--accent); border-color: var(--text-1); color: var(--accent-fg) }

.stat { background: transparent; border: 2px solid var(--text-1) }
.stat b { font-family: var(--font-display); color: var(--accent) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt, #fab {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: var(--surface-1); color: var(--text-1);
  border: 2px solid var(--text-1); border-radius: 0;
}
button.mb-btn:active, .mb-act:active { background: var(--text-1); color: var(--surface-1) }
.mb-btn.go { background: var(--accent); color: var(--accent-fg); border-color: var(--text-1) }
.mb-input, .mb-sel { background: var(--surface-2); border: 2px solid var(--text-1);
  border-radius: 0; color: var(--text-1) }
#fab { background: var(--surface-1); color: var(--accent); border-radius: 0; border-width: 4px }

/* FFVII - the PlayStation menu. Every panel is a translucent blue box graded
   from near-black at the bottom to a lit blue at the top, edged with a thin
   pale line, with white text that carries a hard shadow. */
body { letter-spacing: var(--track-body) }

header {
  background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  border-bottom: var(--border-width) solid var(--border-strong);
}
header .logo { font-family: var(--font-display); color: var(--text-1);
  text-shadow: 2px 2px 0 rgba(0,0,0,.7) }
header .logo b { color: var(--accent) }

.card, .mb-sheet, .mb-menu, .mb-toast {
  background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  border: var(--border-width) solid var(--border-strong);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.5);
}
h2 { font-family: var(--font-display); color: var(--text-1);
  text-shadow: 2px 2px 0 rgba(0,0,0,.6);
  border-bottom: var(--border-width) solid var(--border); padding-bottom: var(--s-2) }

.item { background: transparent; border: 0 }
.item .nm { text-shadow: 1px 1px 0 rgba(0,0,0,.6) }
.item.on .nm { color: var(--accent) }
/* the hand cursor, as a triangle on the live row */
.item::before { content: ''; width: 0; height: 0; flex: 0 0 auto; margin-right: -4px;
  border-left: 8px solid transparent; border-top: 5px solid transparent;
  border-bottom: 5px solid transparent }
.item.on::before { border-left-color: var(--accent) }

.chk { border-color: var(--border-strong) }
.chk.on { background: var(--accent); border-color: var(--accent); color: var(--accent-fg) }

.stat { background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  border: var(--border-width) solid var(--border) }
.stat b { font-family: var(--font-display); color: var(--text-1);
  text-shadow: 2px 2px 0 rgba(0,0,0,.6) }

button.mb-btn, .mb-act, .mb-chip, .mb-x, .mb-opt {
  font-family: var(--font-display); letter-spacing: var(--track-cap);
  background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  color: var(--text-1); border: var(--border-width) solid var(--border-strong);
  text-shadow: 1px 1px 0 rgba(0,0,0,.6);
}
button.mb-btn:active, .mb-act:active { color: var(--accent) }
.mb-btn.go { border-color: var(--accent); color: var(--accent) }
.mb-input, .mb-sel { background: rgba(0,0,0,.35);
  border: var(--border-width) solid var(--border-strong); color: var(--text-1) }
#fab { background: linear-gradient(180deg, var(--surface-3), var(--surface-1));
  color: var(--accent); border: 2px solid var(--border-strong) }
